"use strict";

/**
 * Regenerate the embedding-template fixtures by running the OLD implementation.
 *
 * The templates decide what every vector already in Atlas means, so the new code is
 * pinned against output produced by the original `utils/embeddingGenerator.js` rather
 * than against output produced by the new code. That is the whole point: a fixture the
 * new code generated would prove nothing.
 *
 * Requires the read-only reference clone:
 *   git clone --branch master https://github.com/moonman369/Portfolio-Stats-API \
 *     ../Portfolio-Stats-API-ref
 *
 * Usage:
 *   node scripts/generate-embedding-fixtures.js
 *
 * Writes test/fixtures/embedding-templates.json. Re-run only if the old repo changes;
 * the file is committed so the test suite needs neither the clone nor the network.
 */

const fs = require("node:fs");
const path = require("node:path");

const REF_REPO = path.join(__dirname, "..", "..", "Portfolio-Stats-API-ref");
const OUTPUT = path.join(__dirname, "..", "test", "fixtures", "embedding-templates.json");

// The budget the old code reads from GEMINI_MAX_INPUT_CHARS, pinned so a stray
// environment variable cannot change what gets baked into the fixtures.
const MAX_INPUT_CHARS = 28_000;

const DOCUMENTS = [
  {
    name: "full document",
    document: {
      title: "Ayan Maiti - Professional Resume Overview",
      tags: ["java", "springboot", "dotnet", "azure", "microservices", "generative-ai"],
      summary_for_embedding:
        "java, springboot, dotnet, azure, microservices, generative-ai, systems, engineer",
      content_full:
        "Ayan Maiti is a Systems Engineer at Tata Consultancy Services working on Azure-based integration systems for retail accounts.",
    },
  },
  {
    name: "null content_full",
    document: {
      title: "AWS Certified Developer - Associate",
      tags: ["aws", "cloud", "serverless"],
      summary_for_embedding: "Earned AWS Certified Developer Associate credential in 2024.",
      content_full: null,
    },
  },
  {
    name: "no tags",
    document: {
      title: "Overall Professional Profile Summary",
      tags: [],
      summary_for_embedding: "Experienced backend-focused software engineer.",
      content_full: "Overall profile summary combining experience and strengths.",
    },
  },
  {
    name: "missing title falls back to 'none'",
    document: {
      tags: ["nodejs"],
      summary_for_embedding: "Backend APIs with Node.js and Express.",
      content_full: null,
    },
  },
  {
    name: "truncation: content_full tail is trimmed at a word boundary",
    document: {
      title: "Very Long Project Writeup",
      tags: ["rag", "vector-databases", "search"],
      summary_for_embedding: "A long-form writeup that overflows the character budget.",
      // Comfortably past the 28k budget, with spaces so the word-boundary rule engages.
      content_full: `${"retrieval augmented generation pipeline ".repeat(900)}END`,
    },
  },
];

const QUERIES = [
  "What backend technologies does Ayan work with?",
  "certifications",
  "   whitespace around the query   ",
  "How has Ayan upskilled in AI since 2023, and what did he build with it?",
  `${"a very long query ".repeat(2000)}tail`,
];

function main() {
  if (!fs.existsSync(REF_REPO)) {
    throw new Error(`Reference clone not found at ${REF_REPO} - see the header of this file`);
  }

  // The old module reads this at require time.
  process.env.GEMINI_MAX_INPUT_CHARS = String(MAX_INPUT_CHARS);

  const generatorPath = path.join(REF_REPO, "utils", "embeddingGenerator.js");
  // eslint-disable-next-line import/no-dynamic-require, global-require
  const { buildEmbeddingText, buildQueryEmbeddingText } = require(generatorPath);

  const oldConfig = require(path.join(REF_REPO, "config", "vectorConfig.js"));
  if (oldConfig.MAX_EMBEDDING_INPUT_CHARS !== MAX_INPUT_CHARS) {
    throw new Error(
      `Old config resolved MAX_EMBEDDING_INPUT_CHARS to ${oldConfig.MAX_EMBEDDING_INPUT_CHARS}, expected ${MAX_INPUT_CHARS}`,
    );
  }

  const fixtures = {
    _comment:
      "Generated by running the OLD Portfolio-Stats-API utils/embeddingGenerator.js. Do not hand-edit: regenerate with scripts/generate-embedding-fixtures.js.",
    maxInputChars: MAX_INPUT_CHARS,
    documents: DOCUMENTS.map(({ name, document }) => ({
      name,
      document,
      expected: buildEmbeddingText(document),
    })),
    queries: QUERIES.map((query) => ({ query, expected: buildQueryEmbeddingText(query) })),
  };

  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.writeFileSync(OUTPUT, `${JSON.stringify(fixtures, null, 2)}\n`, "utf8");

  process.stdout.write(
    `wrote ${path.relative(process.cwd(), OUTPUT)}: ${fixtures.documents.length} documents, ${fixtures.queries.length} queries\n`,
  );
  fixtures.documents.forEach((f) => {
    process.stdout.write(`  ${String(f.expected.length).padStart(6)} chars  ${f.name}\n`);
  });
}

main();
